2	import { BlockId, type WorldType } from "@/lib/world";
3	import type { GameMode } from "./gameModes";
4	import type { Difficulty } from "./difficulties";
5	
6	export type ItemKind = "block" | "weapon" | "tool" | "armor" | "food" | "material";
7	export type ArmorSlot = "helmet" | "face_mask" | "neck_protection" | "chestplate" | "leggings" | "boots";
8	/** The worn armor pieces, one per slot — the actual item instance (or null). Equipping moves the piece here, out of the inventory. */
9	export type EquippedArmor = Record<ArmorSlot, InventorySlot | null>;
10	
11	/** A timed status effect on the player. Positive effects come from potions; poison is a hazard. */
12	export type EffectId = "speed" | "strength" | "regeneration" | "fire_resistance" | "water_breathing" | "poison";
13	
14	/** The effect a drinkable potion applies, with how long it lasts. */
15	export type ItemEffect = { id: EffectId; durationSeconds: number };
16	
17	/** A gear enchantment applied at the enchanting table; each maps to one combat/mining/durability seam. */
18	export type EnchantmentId = "sharpness" | "protection" | "efficiency" | "unbreaking" | "mending";
19	
20	/** A per-item-instance enchantment and its level. */
21	export type Enchantment = { id: EnchantmentId; level: number };
22	
23	export type ItemDef = {
24	  id: string;
25	  label: string;
26	  kind: ItemKind;
27	  blockId?: BlockId;
28	  attack?: number;
29	  meleeReach?: number;
30	  throwDamage?: number;
31	  minePower?: number;
32	  mineTier?: number;
33	  armorSlot?: ArmorSlot;
34	  defense?: number;
35	  maxDurability?: number;
36	  /** Hunger points restored when eaten (food items only). */
37	  hunger?: number;
38	  /** The status effect this potion applies when drunk (potion items only). */
39	  effect?: ItemEffect;
40	};
41	
42	export type InventorySlot = {
43	  id: string | null;
44	  label: string;
45	  kind: ItemKind | null;
46	  count: number;
47	  blockId?: BlockId;
48	  attack?: number;
49	  meleeReach?: number;
50	  throwDamage?: number;
51	  minePower?: number;
52	  mineTier?: number;
53	  armorSlot?: ArmorSlot;
54	  defense?: number;
55	  durability?: number;
56	  maxDurability?: number;
57	  hunger?: number;
58	  effect?: ItemEffect;
59	  /** Per-instance enchantments (durable gear only) — applied at the enchanting table. */
60	  enchantments?: Enchantment[];
61	  /** Player-set name from the anvil (durable gear only); falls back to `label` for display. */
62	  customName?: string;
63	};
64	
65	export type Recipe = {
66	  id: string;
67	  label: string;
68	  cost: Array<{ slotId: string; count: number }>;
69	  result: { slotId: string; count: number };
70	  /**
71	   * Station required for this recipe; omitted means the basic crafting grid.
72	   * "furnace" smelts; "villager" is a trade offer, unlocked while trading with a
73	   * villager; "brewing" is a potion recipe, unlocked at a brewing stand.
74	   */
75	  station?: "furnace" | "villager" | "brewing";
76	};
77	
78	export type MobKind = "sheep" | "chicken" | "horse" | "cow" | "pig" | "zombie" | "skeleton" | "spider" | "creeper" | "villager" | "boss";
79	
80	export type MobModel = {
81	  group: THREE.Group;
82	  legs: THREE.Mesh[];
83	  halfHeight: number;
84	  materials: THREE.Material[];
85	  geometries: THREE.BufferGeometry[];
86	};
87	
88	/** A persisted inventory/container slot: just enough to rebuild it on load. */
89	export type SavedSlot = { id: string | null; count: number; durability?: number; enchantments?: Enchantment[]; customName?: string };
90	
91	/** Legacy persisted armor (v1–v11): a by-id reference into the inventory. */
92	export type SavedArmorById = Partial<Record<ArmorSlot, string | null>>;
93	/** Persisted armor (v12+): the worn piece itself, stored per slot via the shared SavedSlot shape. */
94	export type SavedEquippedArmor = Partial<Record<ArmorSlot, SavedSlot>>;
95	
96	/** A block-entity: a placed chest's contents, keyed by its voxel index. */
97	export type SavedContainer = { index: number; slots: SavedSlot[] };
98	
99	/** Legacy save shape (40 inventory slots, 10-slot hotbar) — accepted and migrated on load. */
100	export type SaveDataV1 = {
101	  version: 1;
102	  seed: number;
103	  changes: Array<[number, number]>;
104	  inventoryCounts?: Record<string, number>;
105	  inventorySlots?: SavedSlot[];
106	  equippedArmor?: SavedArmorById;
107	  selectedSlot: number;
108	  player: { x: number; y: number; z: number };
109	};
110	
111	/** v2 save shape: same fields as v1, reinterpreted for 36 slots / 9-slot hotbar. */
112	export type SaveDataV2 = Omit<SaveDataV1, "version"> & { version: 2 };
113	
114	/**
115	 * v3 save shape: v2 plus persisted time-of-day, player stats, and the bed
116	 * respawn point. All added fields are optional so the v2→v3 migration is a pure
117	 * version bump and pre-v3 saves load with sensible defaults.
118	 */
119	export type SaveDataV3 = Omit<SaveDataV2, "version"> & {
120	  version: 3;
121	  dayClock?: number;
122	  hearts?: number;
123	  hunger?: number;
124	  spawnPoint?: { x: number; y: number; z: number } | null;
125	};
126	
127	/**
128	 * v4 save shape: v3 plus chest contents as block-entities. The field is
129	 * optional so the v3→v4 migration is a pure version bump and pre-v4 saves load
130	 * with no containers.
131	 */
132	export type SaveDataV4 = Omit<SaveDataV3, "version"> & {
133	  version: 4;
134	  blockEntities?: SavedContainer[];
135	};
136	
137	/**
138	 * v5 save shape: v4 plus the set of dungeon loot-chest voxel indices the player
139	 * has already opened or broken. Dungeon chests are filled lazily on first access
140	 * and this set — not the chest's emptiness — is what prevents a re-roll on reload
141	 * (an emptied chest is dropped from `blockEntities`). The field is optional so
142	 * the v4→v5 migration is a pure version bump.
143	 */
144	export type SaveDataV5 = Omit<SaveDataV4, "version"> & {
145	  version: 5;
146	  lootedChests?: number[];
147	  /** Generation preset; absent ⇒ "default" (pre-feature and legacy saves). Like `seed`, fixed for the world's life. */
148	  worldType?: WorldType;
149	};
150	
151	/** One persisted status effect: its id and the seconds remaining when saved. */
152	export type SavedEffect = { id: EffectId; remaining: number };
153	
154	/**
155	 * v6 save shape: v5 plus the active status effects (with their remaining
156	 * seconds). The field is optional so the v5→v6 migration is a pure version bump
157	 * and pre-effect saves load with none. Effects are cleared on death, so a
158	 * saved-then-reloaded world restores whatever was active at save.
159	 */
160	export type SaveDataV6 = Omit<SaveDataV5, "version"> & {
161	  version: 6;
162	  effects?: SavedEffect[];
163	};
164	
165	/**
166	 * v7 save shape: v6 plus banked XP (`xp`). Enchantments ride inside each
167	 * `SavedSlot` (additive). Both are optional, so the v6→v7 migration is a pure
168	 * version bump and pre-XP saves load with `xp` 0 and no enchantments. Unlike
169	 * effects, XP is a long-term currency and is NOT cleared on death.
170	 */
171	export type SaveDataV7 = Omit<SaveDataV6, "version"> & {
172	  version: 7;
173	  xp?: number;
174	};
175	
176	/**
177	 * v8 save shape: v7 plus the player's game mode (`gameMode`). The field is
178	 * optional, so the v7→v8 migration is a pure version bump and pre-mode saves
179	 * load as "survival". Unlike `worldType` (fixed for the world's life),
180	 * `gameMode` is switchable in-game, so the saved value is the *current* mode.
181	 */
182	export type SaveDataV8 = Omit<SaveDataV7, "version"> & {
183	  version: 8;
184	  gameMode?: GameMode;
185	};
186	
187	/**
