import * as THREE from "three";
import { BlockId, type WorldType } from "@/lib/world";
import type { GameMode } from "./gameModes";
import type { Difficulty } from "./difficulties";

export type ItemKind = "block" | "weapon" | "tool" | "armor" | "food" | "material";
export type ArmorSlot = "helmet" | "face_mask" | "neck_protection" | "chestplate" | "leggings" | "boots";
/** The worn armor pieces, one per slot — the actual item instance (or null). Equipping moves the piece here, out of the inventory. */
export type EquippedArmor = Record<ArmorSlot, InventorySlot | null>;

/** A timed status effect on the player. Positive effects come from potions; poison is a hazard. */
export type EffectId = "speed" | "strength" | "regeneration" | "fire_resistance" | "water_breathing" | "poison";

/** The effect a drinkable potion applies, with how long it lasts. */
export type ItemEffect = { id: EffectId; durationSeconds: number };

/** A gear enchantment applied at the enchanting table; each maps to one combat/mining/durability seam. */
export type EnchantmentId = "sharpness" | "protection" | "efficiency" | "unbreaking" | "mending" | "power" | "punch" | "knockback" | "looting";

/** A per-item-instance enchantment and its level. */
export type Enchantment = { id: EnchantmentId; level: number };

export type ItemDef = {
  id: string;
  label: string;
  kind: ItemKind;
  blockId?: BlockId;
  attack?: number;
  meleeReach?: number;
  throwDamage?: number;
  minePower?: number;
  mineTier?: number;
  armorSlot?: ArmorSlot;
  defense?: number;
  maxDurability?: number;
  /** Hunger points restored when eaten (food items only). */
  hunger?: number;
  /** The status effect this potion applies when drunk (potion items only). */
  effect?: ItemEffect;
};

export type InventorySlot = {
  id: string | null;
  label: string;
  kind: ItemKind | null;
  count: number;
  blockId?: BlockId;
  attack?: number;
  meleeReach?: number;
  throwDamage?: number;
  minePower?: number;
  mineTier?: number;
  armorSlot?: ArmorSlot;
  defense?: number;
  durability?: number;
  maxDurability?: number;
  hunger?: number;
  effect?: ItemEffect;
  /** Per-instance enchantments (durable gear only) — applied at the enchanting table. */
  enchantments?: Enchantment[];
  /** Player-set name from the anvil (durable gear only); falls back to `label` for display. */
  customName?: string;
};

export type Recipe = {
  id: string;
  label: string;
  cost: Array<{ slotId: string; count: number }>;
  result: { slotId: string; count: number };
  /**
   * Station required for this recipe; omitted means the basic crafting grid.
   * "furnace" smelts; "villager" is a trade offer, unlocked while trading with a
   * villager; "brewing" is a potion recipe, unlocked at a brewing stand.
   */
  station?: "furnace" | "villager" | "brewing";
};

export type MobKind = "sheep" | "chicken" | "horse" | "cow" | "pig" | "zombie" | "skeleton" | "spider" | "creeper" | "villager" | "boss";

export type MobModel = {
  group: THREE.Group;
  legs: THREE.Mesh[];
  halfHeight: number;
  materials: THREE.Material[];
  geometries: THREE.BufferGeometry[];
};

/** A persisted inventory/container slot: just enough to rebuild it on load. */
export type SavedSlot = { id: string | null; count: number; durability?: number; enchantments?: Enchantment[]; customName?: string };

/** Legacy persisted armor (v1–v11): a by-id reference into the inventory. */
export type SavedArmorById = Partial<Record<ArmorSlot, string | null>>;
/** Persisted armor (v12+): the worn piece itself, stored per slot via the shared SavedSlot shape. */
export type SavedEquippedArmor = Partial<Record<ArmorSlot, SavedSlot>>;

/** A block-entity: a placed chest's contents, keyed by its voxel index. */
export type SavedContainer = { index: number; slots: SavedSlot[] };

/** Legacy save shape (40 inventory slots, 10-slot hotbar) — accepted and migrated on load. */
export type SaveDataV1 = {
  version: 1;
  seed: number;
  changes: Array<[number, number]>;
  inventoryCounts?: Record<string, number>;
  inventorySlots?: SavedSlot[];
  equippedArmor?: SavedArmorById;
  selectedSlot: number;
  player: { x: number; y: number; z: number };
};

/** v2 save shape: same fields as v1, reinterpreted for 36 slots / 9-slot hotbar. */
export type SaveDataV2 = Omit<SaveDataV1, "version"> & { version: 2 };

/**
 * v3 save shape: v2 plus persisted time-of-day, player stats, and the bed
 * respawn point. All added fields are optional so the v2→v3 migration is a pure
 * version bump and pre-v3 saves load with sensible defaults.
 */
export type SaveDataV3 = Omit<SaveDataV2, "version"> & {
  version: 3;
  dayClock?: number;
  hearts?: number;
  hunger?: number;
  spawnPoint?: { x: number; y: number; z: number } | null;
};

/**
 * v4 save shape: v3 plus chest contents as block-entities. The field is
 * optional so the v3→v4 migration is a pure version bump and pre-v4 saves load
 * with no containers.
 */
export type SaveDataV4 = Omit<SaveDataV3, "version"> & {
  version: 4;
  blockEntities?: SavedContainer[];
};

/**
 * v5 save shape: v4 plus the set of dungeon loot-chest voxel indices the player
 * has already opened or broken. Dungeon chests are filled lazily on first access
 * and this set — not the chest's emptiness — is what prevents a re-roll on reload
 * (an emptied chest is dropped from `blockEntities`). The field is optional so
 * the v4→v5 migration is a pure version bump.
 */
export type SaveDataV5 = Omit<SaveDataV4, "version"> & {
  version: 5;
  lootedChests?: number[];
  /** Generation preset; absent ⇒ "default" (pre-feature and legacy saves). Like `seed`, fixed for the world's life. */
  worldType?: WorldType;
};

/** One persisted status effect: its id and the seconds remaining when saved. */
export type SavedEffect = { id: EffectId; remaining: number };

/**
 * v6 save shape: v5 plus the active status effects (with their remaining
 * seconds). The field is optional so the v5→v6 migration is a pure version bump
 * and pre-effect saves load with none. Effects are cleared on death, so a
 * saved-then-reloaded world restores whatever was active at save.
 */
export type SaveDataV6 = Omit<SaveDataV5, "version"> & {
  version: 6;
  effects?: SavedEffect[];
};

/**
 * v7 save shape: v6 plus banked XP (`xp`). Enchantments ride inside each
 * `SavedSlot` (additive). Both are optional, so the v6→v7 migration is a pure
 * version bump and pre-XP saves load with `xp` 0 and no enchantments. Unlike
 * effects, XP is a long-term currency and is NOT cleared on death.
 */
export type SaveDataV7 = Omit<SaveDataV6, "version"> & {
  version: 7;
  xp?: number;
};

/**
 * v8 save shape: v7 plus the player's game mode (`gameMode`). The field is
 * optional, so the v7→v8 migration is a pure version bump and pre-mode saves
 * load as "survival". Unlike `worldType` (fixed for the world's life),
 * `gameMode` is switchable in-game, so the saved value is the *current* mode.
 */
export type SaveDataV8 = Omit<SaveDataV7, "version"> & {
  version: 8;
  gameMode?: GameMode;
};

/**
 * v9 save shape: v8 plus the player's difficulty (`difficulty`). The field is
 * optional, so the v8→v9 migration is a pure version bump and pre-v9 saves load
 * as "normal". Like `gameMode`, difficulty is switchable in-game, so the saved
 * value is the *current* difficulty.
 */
export type SaveDataV9 = Omit<SaveDataV8, "version"> & {
  version: 9;
  difficulty?: Difficulty;
};

/**
 * v10 save shape: v9 plus the Hardcore flag (`hardcore`, immutable for the
 * world's life) and the permadeath `gameOver` flag (set once a hardcore run has
 * ended). Both are optional, so the v9→v10 migration is a pure version bump and
 * pre-v10 saves load as a normal, non-hardcore world. A persisted `gameOver`
 * reloads straight into the spectator "dead world" state, never a playable one.
 */
export type SaveDataV10 = Omit<SaveDataV9, "version"> & {
  version: 10;
  hardcore?: boolean;
  gameOver?: boolean;
};

/**
 * v11 save shape: v10 plus a per-item `customName` (the anvil rename), which rides
 * inside each `SavedSlot` (additive). The Mending enchantment rides the existing
 * per-slot `enchantments`, so it adds no new field. The v10→v11 migration is a
 * pure version bump and pre-v11 saves load with no custom names.
 */
export type SaveDataV11 = Omit<SaveDataV10, "version"> & {
  version: 11;
};

/**
 * Current save shape (v12): armor moves to dedicated storage. `equippedArmor` is no
 * longer a by-id reference into the inventory (`SavedArmorById`) but the worn pieces
 * themselves (`SavedEquippedArmor`, per-slot `SavedSlot`). The v11→v12 migration
 * moves each legacy by-id equip out of `inventorySlots` into the armor record so a
 * worn piece no longer double-occupies an inventory slot.
 */
export type SaveData = Omit<SaveDataV11, "version" | "equippedArmor"> & {
  version: 12;
  equippedArmor?: SavedEquippedArmor;
};

import {
  EFFICIENCY_SPEED_PER_LEVEL,
  ENCHANT_MAX_LEVEL,
  KNOCKBACK_PER_LEVEL,
  MENDING_MAX_LEVEL,
  MENDING_REPAIR_PER_XP,
  POWER_DAMAGE_PER_LEVEL,
  PROTECTION_DEFENSE_PER_LEVEL,
  PUNCH_KNOCKBACK_PER_LEVEL,
  SHARPNESS_DAMAGE_PER_LEVEL,
  UNBREAKING_SKIP_PER_LEVEL
} from "@/lib/game/config";
import { ARMOR_SLOTS } from "@/lib/game/items";
import type { Enchantment, EnchantmentId, EquippedArmor, InventorySlot, ItemKind } from "@/lib/game/types";

/**
 * Enchantments are per-item-instance data (like durability) applied at the
 * enchanting table. Each is a flat per-level modifier read at exactly one
 * existing seam — the same one-reader-per-seam discipline as status effects:
 * Sharpness → melee damage, Protection → equipped defense, Efficiency → mining
 * speed, Unbreaking → durability wear. Applies only to durable gear.
 */

export type EnchantmentDef = {
  id: EnchantmentId;
  label: string;
  /** Item kinds this enchantment can be applied to. */
  kinds: ItemKind[];
  /**
   * Optional allow-list of specific item ids: when set, the slot's item must be
   * one of these (on top of the `kinds` gate). Used to bind a weapon enchant to a
   * single item — Power/Punch are bow-only, not for swords (which also are `weapon`).
   */
  itemIds?: string[];
  maxLevel: number;
};

export const ENCHANTMENT_DEFS: Record<EnchantmentId, EnchantmentDef> = {
  sharpness: { id: "sharpness", label: "Sharpness", kinds: ["weapon"], maxLevel: ENCHANT_MAX_LEVEL },
  protection: { id: "protection", label: "Protection", kinds: ["armor"], maxLevel: ENCHANT_MAX_LEVEL },
  efficiency: { id: "efficiency", label: "Efficiency", kinds: ["tool"], maxLevel: ENCHANT_MAX_LEVEL },
  unbreaking: { id: "unbreaking", label: "Unbreaking", kinds: ["tool", "weapon", "armor"], maxLevel: ENCHANT_MAX_LEVEL },
  mending: { id: "mending", label: "Mending", kinds: ["tool", "weapon", "armor"], maxLevel: MENDING_MAX_LEVEL },
  power: { id: "power", label: "Power", kinds: ["weapon"], itemIds: ["bow"], maxLevel: ENCHANT_MAX_LEVEL },
  punch: { id: "punch", label: "Punch", kinds: ["weapon"], itemIds: ["bow"], maxLevel: ENCHANT_MAX_LEVEL },
  knockback: { id: "knockback", label: "Knockback", kinds: ["weapon"], maxLevel: ENCHANT_MAX_LEVEL },
  looting: { id: "looting", label: "Looting", kinds: ["weapon"], maxLevel: ENCHANT_MAX_LEVEL }
};

/** Stable display order for the enchanting panel. */
export const ENCHANTMENT_ORDER: readonly EnchantmentId[] = [
  "sharpness",
  "knockback",
  "looting",
  "power",
  "punch",
  "protection",
  "efficiency",
  "unbreaking",
  "mending"
];

/** Level of `id` on a slot (0 if absent). */
export function enchantLevel(slot: InventorySlot | null | undefined, id: EnchantmentId): number {
  return slot?.enchantments?.find((e) => e.id === id)?.level ?? 0;
}

/** Whether `id` can be applied to `slot` now — right item kind (and specific item, if gated), owned, below its max level. */
export function canEnchant(slot: InventorySlot | null | undefined, id: EnchantmentId): boolean {
  if (!slot?.id || !slot.kind || slot.count <= 0) return false;
  const def = ENCHANTMENT_DEFS[id];
  if (!def.kinds.includes(slot.kind)) return false;
  if (def.itemIds && !def.itemIds.includes(slot.id)) return false; // item-specific enchant (e.g. bow-only Power/Punch)
  return enchantLevel(slot, id) < def.maxLevel;
}

/** A new slot with `id` added (level 1) or its level bumped by one; returns the slot unchanged if not allowed. */
export function applyEnchant(slot: InventorySlot, id: EnchantmentId): InventorySlot {
  if (!canEnchant(slot, id)) return slot;
  const current = slot.enchantments ?? [];
  const enchantments: Enchantment[] = current.some((e) => e.id === id)
    ? current.map((e) => (e.id === id ? { id, level: e.level + 1 } : e))
    : [...current, { id, level: 1 }];
  return { ...slot, enchantments };
}

// --- Seam readers ---

/** Extra melee damage from Sharpness on the held weapon. */
export function sharpnessBonus(slot: InventorySlot | null | undefined): number {
  return enchantLevel(slot, "sharpness") * SHARPNESS_DAMAGE_PER_LEVEL;
}

/** Extra arrow damage from Power on the held bow. */
export function powerBonus(slot: InventorySlot | null | undefined): number {
  return enchantLevel(slot, "power") * POWER_DAMAGE_PER_LEVEL;
}

/** Extra arrow knockback from Punch on the held bow. */
export function punchKnockback(slot: InventorySlot | null | undefined): number {
  return enchantLevel(slot, "punch") * PUNCH_KNOCKBACK_PER_LEVEL;
}

/** Extra melee knockback impulse from Knockback on the held weapon. */
export function knockbackBonus(slot: InventorySlot | null | undefined): number {
  return enchantLevel(slot, "knockback") * KNOCKBACK_PER_LEVEL;
}

/** Looting level on the held weapon (0 if absent) — feeds the bonus-count roll in rollMobDrops. */
export function lootingLevel(slot: InventorySlot | null | undefined): number {
  return enchantLevel(slot, "looting");
}

/** Extra defense points from Protection on a worn armor piece. */
export function protectionDefense(slot: InventorySlot | null | undefined): number {
  return enchantLevel(slot, "protection") * PROTECTION_DEFENSE_PER_LEVEL;
}

/** Mining-speed multiplier from Efficiency on the held tool (1 when absent). */
export function efficiencyMultiplier(slot: InventorySlot | null | undefined): number {
  return 1 + enchantLevel(slot, "efficiency") * EFFICIENCY_SPEED_PER_LEVEL;
}

/** Whether Unbreaking should skip a point of durability wear this time. */
export function unbreakingSkips(slot: InventorySlot | null | undefined, rng: () => number): boolean {
  const level = enchantLevel(slot, "unbreaking");
  return level > 0 && rng() < level * UNBREAKING_SKIP_PER_LEVEL;
}

/** Repairs one Mending slot with up to `xp` points; returns the repaired slot + XP used, or null when there's nothing to do. */
function repairWithXp(slot: InventorySlot | null | undefined, xp: number): { slot: InventorySlot; xpUsed: number } | null {
  if (!slot?.maxDurability || enchantLevel(slot, "mending") <= 0) return null;
  const missing = slot.maxDurability - (slot.durability ?? slot.maxDurability);
  if (missing <= 0) return null;
  const xpNeeded = Math.ceil(missing / MENDING_REPAIR_PER_XP);
  const xpUsed = Math.min(xp, xpNeeded);
  const repaired = Math.min(missing, xpUsed * MENDING_REPAIR_PER_XP);
  return { slot: { ...slot, durability: (slot.durability ?? slot.maxDurability) + repaired }, xpUsed };
}

/**
 * Mending seam: diverts gained XP to repair the player's damaged, Mending-enchanted
 * gear — the held item first, then worn armor in ARMOR_SLOTS order — at
 * MENDING_REPAIR_PER_XP durability per diverted XP point. Returns (possibly new)
 * slots + equipped records (same refs when nothing was repaired) plus the XP left
 * to bank. The one reader for Mending: `awardXp` is its only caller.
 */
export function mendXp(
  slots: InventorySlot[],
  selectedSlot: number,
  equipped: EquippedArmor,
  xp: number
): { slots: InventorySlot[]; equipped: EquippedArmor; xpLeft: number } {
  if (xp <= 0) return { slots, equipped, xpLeft: xp };
  let remaining = xp;
  let nextSlots = slots;
  let nextEquipped = equipped;

  // Held item first (worn armor lives in `equipped`, a disjoint store).
  if (remaining > 0 && selectedSlot >= 0 && selectedSlot < slots.length) {
    const r = repairWithXp(slots[selectedSlot], remaining);
    if (r) {
      nextSlots = slots.slice();
      nextSlots[selectedSlot] = r.slot;
      remaining -= r.xpUsed;
    }
  }

  // Then each worn armor piece.
  for (const armorSlot of ARMOR_SLOTS) {
    if (remaining <= 0) break;
    const r = repairWithXp(nextEquipped[armorSlot], remaining);
    if (!r) continue;
    if (nextEquipped === equipped) nextEquipped = { ...equipped }; // clone on first write
    nextEquipped[armorSlot] = r.slot;
    remaining -= r.xpUsed;
  }

  return { slots: nextSlots, equipped: nextEquipped, xpLeft: remaining };
}

